"""Path With Maximum Gold — DFS from every gold cell, restoring on the way out.

Time: O(m * n * 4^k)   Space: O(m*n)
"""
from typing import List


class Solution:
    def getMaximumGold(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def walk(i: int, j: int) -> int:
            if not (0 <= i < m and 0 <= j < n) or grid[i][j] == 0:
                return 0
            gold = grid[i][j]
            grid[i][j] = 0
            best = max(walk(i + di, j + dj)
                       for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)))
            grid[i][j] = gold
            return gold + best

        return max((walk(i, j) for i in range(m) for j in range(n)), default=0)
